function (vars) {
	var g = new GridWidget(vars.element, vars.offers);
        g.editable = false;
        g.sortable = false;
        g.filterable = false;
        g.pageable = false;
        g.scrollable = false;
				g.groupable = false;
        var viewResource = "[resource_shortdisplayname[View]]";
        g.commands.push({ name: "view", icon: "k-i-share", text: viewResource, href: "/EarlyPayments/Offer?Id=#:OfferId#" });
        g.columns = [
            { field: "LineNumber", title: "[resource_displayname[linenumber]]", width: 70 },
            { field: "Offer.DebtorState", title: "[resource_displayname[debtorstate]]", description: "[resource_description[debtorstate]]", template: "#= (Offer.DebtorState) ? B2B.transactionStates[Offer.DebtorState]: '' #"},
            { field: "Offer.CreditorState", title: "[resource_displayname[creditorstate]]", description: "[resource_description[creditorstate]]", template: "#= (Offer.CreditorState) ? B2B.transactionStates[Offer.CreditorState]: '' #"},
            { field: "Offer.FunderState", title: "[resource_displayname[funderstate]]", description: "[resource_description[funderstate]]", template: "#= (Offer.FunderState) ? B2B.transactionStates[Offer.FunderState]: '' #"},
            { field: "FundableValue", type: "number", title: "[resource_shortdisplayname[FundableValue]]", attributes: { style: "text-align: right;" }, format: "{0:" + type.moneyFormat + "}", width: 80, attributes:{style:"text-align:right;"} },
						{ field: "LinePrice", title: "[resource_shortdisplayname[OfferValue]]", width: 80, format: "{0:" + type.moneyFormat + "}", attributes:{style:"text-align:right;"} },
            { field: "CurrencyId", type: "string", title: "[resource_shortdisplayname[CurrencyId]]", width: 40 },
            { field: "LastUpdated", type: "date", title: "[resource_shortdisplayname[LastUpdated]]", format: "{0:" + type.dateFormat + "}", width: 80 },
		        { 
              field: "Offer.EarliestRelatedTaxPoint", 
              type: "date",
              title: "[resource_displayname[EarliestRelatedTaxPoint]]", 
              description: "[resource_description[EarliestRelatedTaxPoint]]", 
              width: 80, 
              format: "{0:" + type.dateFormat + "}", 
            }
        ];
        vars.RelatedOffersGrid = g;
        return g;
}
